const input = $input.first();
const binary = input.binary?.data?.data;
const headers = input.json.headers || {};

const header = (name) => {
  const lower = name.toLowerCase();
  for (const [key, value] of Object.entries(headers)) {
    if (key.toLowerCase() === lower) return Array.isArray(value) ? value[0] : value;
  }
  return undefined;
};

const rawBody = binary ? Buffer.from(binary, 'base64').toString('utf8') : '';
let event = null;
let parseError = null;
try {
  event = JSON.parse(rawBody);
} catch (error) {
  parseError = error.message;
}

const timestamp = header('x-ledgerflow-timestamp');
const receivedSignature = String(header('x-ledgerflow-signature') || '').replace(/^v1=/, '');
const idempotencyKey = String(header('idempotency-key') || '');
const deliveryId = String(header('x-ledgerflow-delivery-id') || '');

return [{
  json: {
    rawBody,
    verificationPayload: `${timestamp || ''}.${rawBody}`,
    timestamp,
    receivedSignature,
    idempotencyKey,
    deliveryId,
    event,
    parseError
  }
}];

const item = $input.first().json;
const nowSeconds = Math.floor(Date.now() / 1000);
const timestampNumber = Number(item.timestamp);
const timestampFresh = Number.isFinite(timestampNumber) && Math.abs(nowSeconds - timestampNumber) <= 300;
const signaturePattern = /^[a-f0-9]{64}$/i;

function fixedTimeEqualHex(a, b) {
  if (!signaturePattern.test(a || '') || !signaturePattern.test(b || '')) return false;
  let diff = 0;
  for (let i = 0; i < 64; i += 1) {
    diff |= a.charCodeAt(i) ^ b.charCodeAt(i);
  }
  return diff === 0;
}

const hasSecret = Boolean($vars.LEDGERFLOW_WEBHOOK_SECRET && $vars.LEDGERFLOW_WEBHOOK_SECRET !== 'CHANGE_ME');
const signatureValid = fixedTimeEqualHex(String(item.expectedSignature || ''), String(item.receivedSignature || ''));
const valid = hasSecret && !item.parseError && item.event && item.idempotencyKey && timestampFresh && signatureValid;

const staticData = $getWorkflowStaticData('global');
if (!staticData.ledgerflowProcessedKeys) staticData.ledgerflowProcessedKeys = {};
const processed = staticData.ledgerflowProcessedKeys;
const duplicate = valid && Boolean(processed[item.idempotencyKey]);

if (valid && !duplicate) {
  processed[item.idempotencyKey] = new Date().toISOString();
  const keys = Object.keys(processed);
  if (keys.length > 5000) {
    keys.sort((a, b) => String(processed[a]).localeCompare(String(processed[b])));
    for (const key of keys.slice(0, keys.length - 5000)) delete processed[key];
  }
}

const event = item.event || {};
const data = event.data || {};
const source = event.source || {};
const ignoredEventTypes = new Set(['channel.order.shipping_summary.updated']);
const severityIcon = {
  ERROR: '[ERRO]',
  WARNING: '[ALERTA]',
  INFO: '[INFO]',
  SUCCESS: '[OK]'
}[event.severity] || '[INFO]';

const money = (minor, currency) => {
  if (minor === undefined || minor === null || minor === '') return null;
  const number = Number(minor) / 100;
  if (!Number.isFinite(number)) return String(minor);
  return new Intl.NumberFormat('pt-BR', { style: 'currency', currency: currency || 'BRL' }).format(number);
};

const amount = (value, currency) => {
  if (value === undefined || value === null || value === '') return '-';
  const number = Number(value);
  if (!Number.isFinite(number)) return String(value);
  return new Intl.NumberFormat('pt-BR', { style: 'currency', currency: currency || 'BRL' }).format(number);
};

const date = (value) => {
  if (!value) return '-';
  const parsed = new Date(value);
  if (Number.isNaN(parsed.getTime())) return String(value);
  return parsed.toLocaleString('pt-BR', { timeZone: 'America/Sao_Paulo' });
};

const label = (value) => value || '-';

const confirmedSaleMessage = () => [
  'VENDA CONFIRMADA!',
  '',
  `Produto: ${label(data.productName)}`,
  `Quantidade: ${data.quantity ?? '-'}`,
  `Valor: ${amount(data.valueAmount, data.currency)}`,
  `Comprador: ${label(data.buyerName)}`,
  `Frete: ${label(data.logisticType || data.shippingMode)}`,
  `Envio previsto: ${date(data.handlingEstimateAt || data.deliveryEstimateAt)}`,
  '',
  `Status: ${label(data.paymentStatus || 'Pagamento aprovado')}`,
  `Pedido: ${label(data.externalOrderId || source.id)}`
].join('\n');

const summaryByType = {
  'mercado_pago.payment_status_updated': () => `Pagamento ${data.paymentReference || source.id || '-'} mudou de ${data.previousStatus || '-'} para ${data.currentStatus || '-'}.`,
  'mercado_pago.connection_reauth_required': () => `Reconecte a conta ${data.provider || 'Mercado Pago'} no LedgerFlow.`,
  'marketplace_settlement.event_received': () => {
    const amount = money(data.netAmountMinor, data.currency);
    return `Settlement recebido de ${data.provider || 'provider'}${data.providerPaymentId ? ` para pagamento ${data.providerPaymentId}` : ''}${amount ? ` no valor liquido ${amount}` : ''}.`;
  },
  'cash_position.unexplained_difference': () => {
    const amount = money(data.differenceAmountMinor, data.currency);
    return `Diferenca de caixa sem explicacao${amount ? `: ${amount}` : ''}.`;
  },
  'channel.inventory_sync.failed': () => `Falha ao sincronizar estoque do listing ${data.listingId || source.id || '-'}.`,
  'channel.order.shipping_summary.updated': () => `Resumo de envio atualizado para pedido ${data.externalOrderId || data.orderId || source.id || '-'}.`,
  'reconciliation.case.divergent': () => `Caso de conciliacao divergente: ${data.caseId || source.id || '-'}.`,
  'sale.loss_detected': () => 'Venda com prejuizo detectada.',
  'sale.low_margin_detected': () => 'Venda com margem baixa detectada.',
  'sale.missing_cost_detected': () => 'Venda sem custo cadastrado detectada.',
  'sale.stock_not_consumed': () => 'Venda sem consumo de estoque detectada.',
  'sale.shipping_delayed': () => 'Possivel atraso de envio detectado.',
  'sale.settlement_divergent': () => 'Divergencia de settlement detectada.',
  'sale.cash_release_blocked': () => 'Liberacao de caixa bloqueada detectada.'
};

const occurredAt = event.occurredAt ? new Date(event.occurredAt).toLocaleString('pt-BR', { timeZone: 'America/Sao_Paulo' }) : '-';
const summary = (summaryByType[event.type] || (() => `Evento LedgerFlow recebido: ${event.type || 'desconhecido'}.`))();
const telegramMessage = event.type === 'sale.confirmed'
  ? confirmedSaleMessage()
  : [
    `${severityIcon} LedgerFlow`,
    `Tipo: ${event.type || '-'}`,
    `Categoria: ${event.category || '-'}`,
    `Quando: ${occurredAt}`,
    '',
    summary,
    '',
    `Evento: ${event.id || '-'}`,
    `Delivery: ${item.deliveryId || '-'}`
  ].join('\n');

let invalidReason = null;
if (!hasSecret) invalidReason = 'LEDGERFLOW_WEBHOOK_SECRET ausente ou ainda CHANGE_ME';
else if (item.parseError) invalidReason = `JSON invalido: ${item.parseError}`;
else if (!item.idempotencyKey) invalidReason = 'Idempotency-Key ausente';
else if (!timestampFresh) invalidReason = 'Timestamp ausente ou fora da janela de 5 minutos';
else if (!signatureValid) invalidReason = 'Assinatura HMAC invalida';

return [{
  json: {
    ...item,
    valid,
    duplicate,
    shouldNotify: valid && !duplicate && !ignoredEventTypes.has(event.type),
    invalidReason,
    telegramMessage,
    response: valid
      ? { ok: true, duplicate, ignored: ignoredEventTypes.has(event.type), eventId: event.id || null, deliveryId: item.deliveryId || null }
      : { ok: false, error: invalidReason }
  }
}];
